/**
 * v0.28.0 — PreToolUse:Grep advisor / blocker.
 *
 * When the main-thread agent uses Grep to search for a symbol-like
 * identifier (camelCase, snake_case, PascalCase, ≥4 chars, no regex
 * metacharacters) we suggest `mcp__token-pilot__find_usages` instead.
 * The MCP tool does semantic search — groups results into definitions /
 * imports / usages — and for real symbols is 5-10× cheaper than Grep's
 * line-oriented output.
 *
 * For anything that LOOKS like regex (special chars, quantifiers,
 * alternation) or short generic terms (≤3 chars) we allow Grep through
 * unchanged. Those are cases where semantic search doesn't apply or
 * Grep is genuinely cheaper.
 *
 * This is strictly advisory in the v0.28.0 first pass: we emit
 * permissionDecision: "deny" so the agent sees the suggestion on the
 * first attempt, but the user mandate is passive-as-possible — if
 * adoption data (tool-audit) shows agents actually re-run through
 * find_usages after the block, we keep it. If they bypass via `-E` or
 * raw shell, we soften to advisory.
 */

import type { EnforcementMode } from "../server/enforcement-mode.js";
import { toolPrefix } from "../core/tool-names.js";
import { isCodeFile } from "./read-gate.js";

export interface PreGrepInput {
  tool_name?: string;
  tool_input?: {
    pattern?: string;
    path?: string;
    type?: string;
    [k: string]: unknown;
  };
}

export type PreGrepDecision =
  | { kind: "allow" }
  | { kind: "advise"; reason: string }
  | { kind: "deny"; reason: string };

/**
 * Shapes that look like TODO / FIXME / HACK / XXX / BUG tag scans —
 * route these to `code_audit` which returns deduplicated, categorised
 * results instead of N raw grep hits. Zero code_audit calls across three
 * projects (tool-audit 2026-04-24) = agents reach for Grep every time.
 */
export function isTodoScanPattern(pattern: string): boolean {
  // Strip common grep-alternation syntax to compare the symbol cores
  const normalised = pattern.replace(/[()\s]/g, "").toUpperCase();
  const tagRe =
    /^(TODO|FIXME|HACK|XXX|BUG|NOTE|OPTIMIZE|REFACTOR)(\|(TODO|FIXME|HACK|XXX|BUG|NOTE|OPTIMIZE|REFACTOR))*$/;
  return tagRe.test(normalised);
}

/**
 * Heuristic: does `pattern` look like a code identifier worth sending
 * through find_usages?
 *
 * - Length ≥ 4 (avoid `id`, `err`, `db` — Grep wins there)
 * - No regex metacharacters (`.` `*` `+` `?` `|` `(` `)` `[` `]`
 *   `{` `}` `^` `$` `\`) — if present we assume real regex
 * - camelCase / PascalCase with an inner hump (`getUser`, `UserService`),
 *   snake_case or CONSTANT_CASE.
 *
 * Not identifiers (1.0.2): kebab-case (`token-pilot`, `x-api-key`,
 * `UTF-8` — package names, headers, CSS), a single capitalised word
 * (`Error`, `README`), anything starting with `-`.
 */
export function isSymbolLikePattern(pattern: string): boolean {
  if (pattern.length < 4) return false;

  // Regex metacharacters — if any present, assume user means regex.
  if (/[.*+?|()[\]{}^$\\]/.test(pattern)) return false;

  // A single word of letters, digits and underscores — no spaces, hyphens,
  // leading dashes.
  if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(pattern)) return false;
  if (!/[a-zA-Z]/.test(pattern)) return false;

  const hasUpperInMiddle = /[a-z0-9][A-Z]/.test(pattern);
  const hasUnderscore = /[A-Za-z0-9]_[A-Za-z0-9]/.test(pattern);

  return hasUpperInMiddle || hasUnderscore;
}

/** File types a Grep may be confined to that hold code. */
const CODE_TYPES = new Set([
  "js", "ts", "jsx", "tsx", "py", "rust", "go", "java", "kotlin", "swift",
  "php", "ruby", "c", "cpp", "csharp", "cs", "scala", "dart", "lua", "sh",
  "vue", "svelte", "sql", "elixir", "clojure", "elm", "ocaml", "fsharp",
]);

/** The search is confined to files that are not code (`*.md`, type md, a README). */
function nonCodeScope(input: PreGrepInput["tool_input"]): boolean {
  const glob = input?.glob;
  if (typeof glob === "string" && glob.length > 0) {
    return !globHasCode(glob);
  }

  const type = input?.type;
  if (typeof type === "string" && type.length > 0) return !CODE_TYPES.has(type.toLowerCase());

  const path = input?.path;
  return typeof path === "string" && /\.[A-Za-z0-9]+$/.test(path) && !isCodeFile(path);
}

/** `*.ts`, `src/**\/*.{ts,tsx}` — the glob names at least one code extension. */
function globHasCode(glob: string): boolean {
  const tail = glob.slice(glob.lastIndexOf(".") + 1).replace(/[{}]/g, "");

  return tail.split(",").some((ext) => isCodeFile(`x.${ext.trim()}`));
}

/**
 * Pure decision function. Given a PreToolUse hook input for Grep,
 * return whether to allow or deny (with a suggestion).
 */
export function decidePreGrep(
  input: PreGrepInput,
  mode: EnforcementMode = "deny",
): PreGrepDecision {
  if (input.tool_name !== "Grep") return { kind: "allow" };
  const pattern = input.tool_input?.pattern;
  if (typeof pattern !== "string" || pattern.length === 0) {
    return { kind: "allow" };
  }

  // TODO / FIXME / HACK tag scan → route to code_audit. Emitted as an
  // advisory ("allow" + hint) regardless of enforcement mode: blocking
  // would frustrate a legitimate one-off scan, but nudging the agent
  // toward code_audit compounds the benefit across a session.
  if (isTodoScanPattern(pattern)) {
    return {
      kind: "advise",
      reason:
        `Grep pattern "${pattern}" is a TODO / FIXME / HACK scan. ` +
        `Prefer ${toolPrefix()}code_audit(check="todo") — it returns deduplicated, ` +
        `categorised tags across the project with file/line references, ` +
        `typically 3-5× fewer tokens than raw Grep and ignores generated/` +
        `vendored code automatically.`,
    };
  }

  // Advisory mode disables the symbol-like deny (legacy behaviour).
  if (mode === "advisory") return { kind: "allow" };

  if (!isSymbolLikePattern(pattern)) return { kind: "allow" };

  // Bounded output (file names, counts, a head limit) or a search of
  // non-code files: Grep is the right tool. Claude Code's Grep defaults to
  // "files_with_matches" when output_mode is left out, so only "content"
  // prints matching lines.
  const ti = input.tool_input;
  if (ti?.output_mode !== "content") return { kind: "allow" };
  if (typeof ti?.head_limit === "number" && ti.head_limit > 0) return { kind: "allow" };
  if (nonCodeScope(ti)) return { kind: "allow" };

  const reason =
    `Grep pattern "${pattern}" looks like a code identifier. ` +
    `Use ${toolPrefix()}find_usages(symbol="${pattern}") for semantic ` +
    `search — groups results into definitions / imports / usages, typically ` +
    `5-10× cheaper than Grep's line-oriented output. ` +
    `Need a raw text search anyway (a string literal, a comment)? Bound it: ` +
    `output_mode "files_with_matches" or "count", or a head_limit.`;
  return { kind: "deny", reason };
}

/**
 * Render the Claude Code hook JSON response. Advice carries no
 * permissionDecision: "allow" would skip the user's permission prompt.
 */
export function renderPreGrepOutput(decision: PreGrepDecision): string | null {
  if (decision.kind === "allow") return null;
  if (decision.kind === "advise") {
    return JSON.stringify({
      hookSpecificOutput: {
        hookEventName: "PreToolUse",
        additionalContext: decision.reason,
      },
    });
  }
  return JSON.stringify({
    hookSpecificOutput: {
      hookEventName: "PreToolUse",
      permissionDecision: "deny",
      permissionDecisionReason: decision.reason,
    },
  });
}

files.src/hooks/mcp-path.ts:
/**
 * PreToolUse hook on token-pilot's own MCP tools — keeps relative paths in
 * the checkout the session is actually working in.
 *
 * The MCP server fixes its project root once, when it starts
 * (CLAUDE_PROJECT_DIR). A session that then moves into a git worktree —
 * `cd .worktrees/feature`, the layout superpowers, keel and Claude Code's own
 * worktrees use — kept having relative paths resolved against the main
 * checkout: the same file from another branch, with nothing to say so. It was
 * found on a payment code path during a rebase.
 *
 * Claude Code runs hooks in the session's current directory and applies a
 * PreToolUse `updatedInput` to MCP calls — both verified live on 2.1.281 — so
 * the hook maps relative paths onto the session's checkout before the call
 * reaches the server. Inside the server's own checkout it prints nothing:
 * ordinary sessions see no change at all.
 *
 * Tools that look past a single file — the symbol index, git history and
 * diffs, test runs — still answer from the server's checkout. For those the
 * hook says so, rather than letting the answer pass for the worktree's.
 */

import { isAbsolute, relative, resolve } from "../core/portable-path.js";

export interface McpPathInput {
  tool_name?: string;
  tool_input?: Record<string, unknown>;
  cwd?: string;
}

export interface McpPathContext {
  /** Root the MCP server resolves relative paths against. */
  projectRoot: string | undefined;
  /** The git checkout a directory belongs to, or null outside any. */
  checkoutOf: (dir: string) => string | null;
}

export type McpPathDecision =
  | { kind: "allow" }
  | { kind: "rewrite"; updatedInput: Record<string, unknown>; note?: string }
  | { kind: "warn"; message: string };

/** Tools that read exactly the file they are handed — right once the path is. */
const FILE_TOOLS = new Set([
  "smart_read",
  "read_symbol",
  "read_symbols",
  "read_range",
  "read_section",
  "read_for_edit",
  "read_diff",
  "smart_read_many",
]);

const OUR_TOOL = /^mcp__(?:plugin_token-pilot_token-pilot|token-pilot)__(.+)$/;

export function decideMcpPath(
  input: McpPathInput,
  ctx: McpPathContext,
): McpPathDecision {
  const tool = OUR_TOOL.exec(input.tool_name ?? "")?.[1];
  const { cwd } = input;
  const { projectRoot } = ctx;
  if (!tool || !cwd || !projectRoot) return { kind: "allow" };

  const serverCheckout = ctx.checkoutOf(projectRoot);
  const sessionCheckout = ctx.checkoutOf(cwd);
  if (!serverCheckout || !sessionCheckout || serverCheckout === sessionCheckout) {
    return { kind: "allow" };
  }

  // The server can be rooted in a sub-project of its checkout; the same
  // sub-project is where relative paths belong in the session's checkout.
  const base = resolve(sessionCheckout, relative(serverCheckout, projectRoot));
  const onBase = (p: unknown): unknown =>
    typeof p === "string" && p !== "" && !isAbsolute(p) ? resolve(base, p) : p;

  // Only `path` and `paths` are filesystem paths. `scope` on find_usages is
  // a prefix filter over index entries and must stay relative.
  const args = input.tool_input ?? {};
  const updatedInput: Record<string, unknown> = { ...args };
  let changed = false;

  if ("path" in args && onBase(args.path) !== args.path) {
    updatedInput.path = onBase(args.path);
    changed = true;
  }

  if (Array.isArray(args.paths)) {
    const mapped = args.paths.map(onBase);
    if (mapped.some((p, i) => p !== (args.paths as unknown[])[i])) {
      updatedInput.paths = mapped;
      changed = true;
    }
  }

  const note = FILE_TOOLS.has(tool)
    ? undefined
    : `[token-pilot] This session works in ${sessionCheckout}, but token-pilot's ` +
      `symbol index, git context and test runs are rooted at ${serverCheckout}. ` +
      `${tool} answers from ${serverCheckout} — possibly another branch. Files ` +
      `in this checkout read correctly by path (smart_read, read_symbol).`;

  if (changed) return { kind: "rewrite", updatedInput, note };
  if (note) return { kind: "warn", message: note };

  return { kind: "allow" };
}

/**
 * Claude Code applies `updatedInput` only together with a permission
 * decision. `allow` also skips the approval prompt — acceptable here because
 * the rewrite fires only for token-pilot's own read-only tools, and only when
 * the session is in a different checkout from the server.
 */
export function renderMcpPathOutput(decision: McpPathDecision): string | null {
  if (decision.kind === "allow") return null;

  if (decision.kind === "warn") {
    return JSON.stringify({
      hookSpecificOutput: {
        hookEventName: "PreToolUse",
        additionalContext: decision.message,
      },
    });
  }

  return JSON.stringify({
    hookSpecificOutput: {
      hookEventName: "PreToolUse",
      permissionDecision: "allow",
      updatedInput: decision.updatedInput,
      ...(decision.note ? { additionalContext: decision.note } : {}),
    },
  });
}

files.src/hooks/pre-edit.ts:
/**
 * v0.30.0 — PreToolUse:Edit/MultiEdit/Write enforcement.
 *
 * Background: tool-audit data across three real projects (2026-04-24)
 * showed Codex calling `read_for_edit` at 33% of its MCP volume while
 * Claude sat at 0-1% despite our MCP instructions marking it MANDATORY.
 * Text rules alone don't flip trained agent instincts. The pattern that
 * did move Claude — pre-grep → find_usages — is hook-based deny.
 *
 * This hook closes the gap: before Claude executes Edit/MultiEdit/Write
 * on an existing code file, we check a shared prep-state file that
 * read_for_edit updates on every call. If the file isn't prepared we
 * block (deny) or warn (advisory), depending on TOKEN_PILOT_MODE.
 *
 * Scope rules, in order:
 *   1. Non-code files            → allow (config, markdown, etc.)
 *   2. Write on non-existent file → allow (new-file creation is fine)
 *   3. TOKEN_PILOT_BYPASS=1      → allow (escape hatch)
 *   4. advisory mode             → allow + additionalContext hint
 *   5. File already prepared     → allow
 *   6. Otherwise                 → deny with actionable message
 *
 * The decide function is pure — no I/O, no process.env reads — so it is
 * trivially unit-testable. All side effects (existsSync, state read,
 * enforcement-mode env) are resolved in the thin wrapper before the call.
 */

import type { EnforcementMode } from "../server/enforcement-mode.js";
import { toolPrefix } from "../core/tool-names.js";

export interface PreEditInput {
  tool_name?: string;
  tool_input?: {
    file_path?: string;
    [k: string]: unknown;
  };
}

export type PreEditDecision =
  | { kind: "allow" }
  | { kind: "advise"; message: string }
  | { kind: "deny"; reason: string };

export interface PreEditContext {
  /** Enforcement mode from TOKEN_PILOT_MODE */
  mode: EnforcementMode;
  /** File extension is a code file we care about */
  isCodeFile: boolean;
  /** The target file already exists on disk */
  fileExists: boolean;
  /** read_for_edit was called for this file recently */
  isPrepared: boolean;
  /** TOKEN_PILOT_BYPASS=1 set in env */
  bypassed: boolean;
  /**
   * The file lies outside the project. read_for_edit refuses such paths, so
   * gating them would leave strict mode no way forward.
   */
  outsideProject?: boolean;
}

/**
 * Pure decision function. Caller resolves all context (FS, env, state)
 * beforehand so this stays a deterministic mapping input → decision.
 */
export function decidePreEdit(
  input: PreEditInput,
  ctx: PreEditContext,
): PreEditDecision {
  const toolName = input.tool_name ?? "";
  // Only Edit and MultiEdit touch a file partially with an old_string that
  // MUST match disk byte-for-byte — those are the calls read_for_edit
  // actually prepares. Write replaces the whole file (new content, no
  // old_string) so enforcing prep on Write is overreach: blocks legit
  // script regeneration / template overwrites that never needed prep.
  // Pre-v0.30.3 we blocked Write too; that was wrong. Rolled back.
  if (toolName !== "Edit" && toolName !== "MultiEdit") {
    return { kind: "allow" };
  }

  const filePath = input.tool_input?.file_path;
  if (typeof filePath !== "string" || filePath.length === 0) {
    return { kind: "allow" };
  }

  // Non-code files: config, markdown, JSON — Read-based edit-prep doesn't
  // carry the same value, skip enforcement.
  if (!ctx.isCodeFile) return { kind: "allow" };

  // Non-existent files — Edit/MultiEdit will error downstream in Claude Code
  // itself. Nothing for us to add.
  if (!ctx.fileExists) return { kind: "allow" };

  // Explicit escape hatch. Documented as TOKEN_PILOT_BYPASS=1.
  if (ctx.bypassed) return { kind: "allow" };

  // Already prepared, or a file read_for_edit cannot prepare → allow.
  if (ctx.isPrepared || ctx.outsideProject) return { kind: "allow" };

  const suggestion = `${toolPrefix()}read_for_edit(path="${filePath}", symbol="<target>")`;

  // v0.30.4 — only TOKEN_PILOT_MODE=strict produces a hard deny. The old
  // "deny is default = hard-block every un-prepped Edit" was overreach:
  // two real-project deadlocks reported on 2026-04-24 (MCP briefly
  // disconnected, and an agent that simply forgot to prep). The cost of a
  // false deny (stuck session, user scrambles for TOKEN_PILOT_BYPASS) is
  // much worse than the cost of a missed nudge. Strict mode still exists
  // for users who want the old hard-block behaviour.
  if (ctx.mode === "strict") {
    const reason =
      `File "${filePath}" was not prepared with read_for_edit. ` +
      `Call ${suggestion} FIRST to obtain the exact old_string for Edit — ` +
      `this is the canonical flow. Building old_string from smart_read or Read ` +
      `snippets diverges from disk (whitespace, line-number prefixes) and Edit ` +
      `silently mismatches. ` +
      `If read_for_edit is unavailable, ask the user: they can restart Claude Code ` +
      `with TOKEN_PILOT_MODE=deny (warn only) or TOKEN_PILOT_BYPASS=1.`;
    return { kind: "deny", reason };
  }

  // advisory + deny (default) both yield a non-blocking hint. The agent
  // still runs the Edit; the additionalContext teaches the pattern next
  // time without stranding the user mid-session.
  return {
    kind: "advise",
    message:
      `File "${filePath}" was not prepared with read_for_edit. ` +
      `Consider calling ${suggestion} first — the exact old_string it returns is what Edit actually needs. ` +
      `Edit built from smart_read / Read snippets frequently mismatches on whitespace.`,
  };
}

/**
 * Render the Claude Code hook JSON response.
 *
 * - allow   → no output (hook passes through with no side-effect)
 * - advise  → additionalContext hint only: a permissionDecision of "allow"
 *             would skip the user's permission prompt for the Edit
 * - deny    → permissionDecision=deny + reason
 */
export function renderPreEditOutput(decision: PreEditDecision): string | null {
  if (decision.kind === "allow") return null;
  if (decision.kind === "advise") {
    return JSON.stringify({
      hookSpecificOutput: {
        hookEventName: "PreToolUse",
        additionalContext: decision.message,
      },
    });
  }
  return JSON.stringify({
    hookSpecificOutput: {
      hookEventName: "PreToolUse",
      permissionDecision: "deny",
      permissionDecisionReason: decision.reason,
    },
  });
}

