/**
 * Estimate token count for text content.
 * Uses a simple heuristic calibrated against cl100k_base.
 */
export function estimateTokens(text: string): number {
  if (text.length === 0) return 0;
  const charEstimate = Math.ceil(text.length / 4);
  const whitespaceRatio = (text.match(/\s/g)?.length ?? 0) / text.length;
  const adjustment = 1 - (whitespaceRatio * 0.3);
  return Math.ceil(charEstimate * adjustment);
}

/**
 * Format a token savings message.
 */
export function formatSavings(actual: number, wouldBe: number): string {
  if (wouldBe <= 0) return '';
  const saved = Math.round((1 - actual / wouldBe) * 100);
  return `TOKEN SAVINGS: ~${actual} tokens (structure) vs ~${wouldBe} tokens (full file) = ${saved}% saved`;
}

files.src/core/event-log.ts:
/**
 * Phase 6 subtasks 6.1 + 6.2 — hook-events JSONL log.
 *
 * Writes to `<projectRoot>/.token-pilot/hook-events.jsonl` with the
 * schema specified in TP-c2a acceptance:
 *
 *   { ts, session_id, agent_type, agent_id, event, file, lines,
 *     estTokens, summaryTokens, savedTokens }
 *
 * Rotation: when the current file grows past `ROTATION_THRESHOLD_BYTES`
 * (10 MB), it is renamed to `hook-events.<unix-ms>.jsonl` and a new
 * empty file begins.
 *
 * Retention: `applyRetention` deletes rotated files older than
 * `RETENTION_MAX_AGE_DAYS` (30 days) and trims the directory down to
 * `RETENTION_MAX_TOTAL_BYTES` (100 MB) by removing the oldest archives
 * first. The current file is never deleted.
 *
 * Legacy coexistence: the old `.token-pilot/hook-denied.jsonl` is left
 * in place — this module writes only to the new file.
 */

import { promises as fs } from "node:fs";
import { join } from "node:path";
import {
  ROTATION_THRESHOLD_BYTES,
  diagnosticEvent,
  shouldRotate,
  tagEvent,
  type DiagnosticArgs,
} from "./hook-event.js";

export { ROTATION_THRESHOLD_BYTES, shouldRotate };

export const RETENTION_MAX_AGE_DAYS = 30;
export const RETENTION_MAX_TOTAL_BYTES = 100_000_000;

const CURRENT_FILE = "hook-events.jsonl";
const ARCHIVE_RE = /^hook-events\.\d+\.jsonl$/;

export interface HookEvent {
  ts: number;
  session_id: string;
  /** null for top-level session; agent_type string inside a subagent. */
  agent_type: string | null;
  agent_id: string | null;
  /**
   * v0.34.0 — agent_id of the parent that dispatched this subagent.
   * Claude Code now ships `x-claude-code-parent-agent-id` headers
   * and exposes the value in PostToolUse:Task input. Capturing it
   * lets us reconstruct the full dispatch chain
   * (main → general-purpose → tp-* delegate, etc.) instead of seeing
   * only the leaf agent. Optional — older Claude Code versions
   * never populate it; events stay shape-compatible.
   */
  parent_agent_id?: string | null;
  /**
   * v0.45.0 — root/parent SESSION id (distinct from agent_id). Claude Code
   * exposes `parent_session_id` in subagent hook payloads (binary:
   * `if(D.parentSessionId) X.parent_session_id = D.parentSessionId`). A
   * subagent's MCP server is spawned with CLAUDE_CODE_SESSION_ID = the AGENT
   * session, so its tool-call and denial savings get tagged with that id and
   * the statusline's main-session filter drops them. Capturing the parent lets
   * the badge roll subagent savings up to the conversation that spawned them.
   * Optional — absent on the main thread and on older Claude Code.
   */
  parent_session_id?: string | null;
  /**
   * v0.38.0 — id of the token-pilot workflow this event belongs to,
   * when one is active (TOKEN_PILOT_WORKFLOW_ID set). Lets fleet-level
   * budget + telemetry slice a fan-out run out of the global log.
   * Optional — absent when no workflow is active.
   */
  workflow_id?: string;
  /**
   * Loom spine link — id of the Loom task this event belongs to, when the
   * session was launched by Loom (LOOM_TASK_ID set). Lets Loom attribute token
   * savings to a task exactly. Optional — absent outside Loom, so standalone
   * token-pilot events stay byte-identical to before.
   */
  task_id?: string;
  event:
    | "denied"
    | "allowed"
    | "bypass"
    | "pass-through"
    | "task"
    | "diagnostic"
    | string;
  file: string;
  lines: number;
  estTokens: number;
  /** Tokens delivered back to the agent as the summary; 0 for allow/bypass. */
  summaryTokens: number;
  /** estTokens - summaryTokens; 0 for allow/bypass. */
  savedTokens: number;

  // ─── diagnostic (v0.34.0) ────────────────────────────────────────
  // Populated only on `event: "diagnostic"` records — emitted by
  // hooks/handlers when an edge-case fires (matcher empty, WSL
  // path rejected, validation coerced, …). Every diagnostic gets a
  // stable `code` so frequencies are countable in stats.
  /** "info" | "warn" | "error" — severity of the diagnostic. */
  level?: "info" | "warn" | "error";
  /** Stable searchable identifier — e.g. `force_subagents_no_agents`. */
  code?: string;
  /** Optional small map of context — must be sanitised by caller. */
  detail?: Record<string, unknown>;

  // ─── timing (v0.34.0 Pack 3) ─────────────────────────────────────
  /**
   * Wall-clock duration of the hook handler that emitted this event,
   * milliseconds. Always optional — only the safe-runner wrapper sets
   * it, and only on the FINAL diagnostic record per hook invocation.
   */
  duration_ms?: number;

  // ─── task-specific (v0.31.0) ─────────────────────────────────────
  // These are populated only on `event: "task"` records emitted by
  // `processPostTask`. They are optional on the interface so the rest
  // of the pipeline (existing Read/Bash events) stays unchanged.
  /** The subagent_type Claude Code dispatched (`tp-*` or `general-purpose`…). */
  subagent_type?: string;
  /**
   * Heuristic match against `tp-*` agent frontmatter. Set only when
   * `subagent_type` is NOT already a tp-*. null when no match fires.
   */
  matched_tp_agent?: string | null;
  /** Confidence of the heuristic match (omitted when matched_tp_agent=null). */
  match_confidence?: "high" | "low";
  /** Response budget declared in the agent markdown body, or null. */
  budget?: number | null;
  /** actualTokens > budget × (1 + tolerance). */
  overBudget?: boolean;
}

export function eventLogDir(projectRoot: string): string {
  return join(projectRoot, ".token-pilot");
}

export function currentLogPath(projectRoot: string): string {
  return join(eventLogDir(projectRoot), CURRENT_FILE);
}

// ─── pure: rotation predicate ───────────────────────────────────────────────


// ─── pure: retention policy ─────────────────────────────────────────────────

/**
 * Given the full list of archive files with their mtime + size, return
 * the subset whose paths should be deleted to satisfy:
 *   (a) maxAgeDays — delete anything older
 *   (b) maxTotalBytes — delete oldest first until total fits
 *
 * `now` is passed in to keep the function deterministic for tests.
 */
export function retentionDeletions(
  files: Array<{ path: string; mtime: Date; size: number }>,
  now: Date,
  maxAgeDays: number = RETENTION_MAX_AGE_DAYS,
  maxTotalBytes: number = RETENTION_MAX_TOTAL_BYTES,
): string[] {
  const toDelete = new Set<string>();
  const maxAgeMs = maxAgeDays * 86_400_000;

  // (a) age-based
  const survivors: Array<{ path: string; mtime: Date; size: number }> = [];
  for (const f of files) {
    if (now.getTime() - f.mtime.getTime() > maxAgeMs) {
      toDelete.add(f.path);
    } else {
      survivors.push(f);
    }
  }

  // (b) size-based — delete oldest first from survivors until cap is met
  const totalSize = survivors.reduce((sum, f) => sum + f.size, 0);
  if (totalSize > maxTotalBytes) {
    const byOldest = [...survivors].sort(
      (a, b) => a.mtime.getTime() - b.mtime.getTime(),
    );
    let trimmed = totalSize;
    for (const f of byOldest) {
      if (trimmed <= maxTotalBytes) break;
      toDelete.add(f.path);
      trimmed -= f.size;
    }
  }

  return [...toDelete];
}

// ─── FS wrappers ────────────────────────────────────────────────────────────

async function ensureLogDir(projectRoot: string): Promise<void> {
  await fs.mkdir(eventLogDir(projectRoot), { recursive: true });
}

async function rotateIfNeeded(
  projectRoot: string,
  thresholdBytes: number = ROTATION_THRESHOLD_BYTES,
): Promise<void> {
  const current = currentLogPath(projectRoot);
  let stat: { size: number };
  try {
    const s = await fs.stat(current);
    stat = { size: s.size };
  } catch {
    return; // no current file → nothing to rotate
  }
  if (!shouldRotate(stat, thresholdBytes)) return;
  const archivePath = join(
    eventLogDir(projectRoot),
    `hook-events.${Date.now()}.jsonl`,
  );
  try {
    await fs.rename(current, archivePath);
  } catch {
    // Rename raced with another process; caller will just append onto
    // whichever file now exists.
  }
}

/**
 * Append one event to the current log file. Rotates first if the
 * current file has reached the threshold. Never throws — a failure
 * here must not break hook dispatch.
 */
export async function appendEvent(
  projectRoot: string,
  event: HookEvent,
): Promise<void> {
  try {
    // v0.38.0 — auto-tag with the active workflow id so every event
    // emitted inside a `token-pilot workflow` boundary is sliceable.
    // Read the env var directly here to keep call sites unchanged; an
    // explicit workflow_id on the event always wins.
    // Loom spine: the task id too. Env-driven so call sites stay unchanged.
    const tagged = tagEvent(event, process.env);
    await ensureLogDir(projectRoot);
    await rotateIfNeeded(projectRoot);
    const line = JSON.stringify(tagged) + "\n";
    await fs.appendFile(currentLogPath(projectRoot), line);
  } catch {
    /* silent — telemetry is best-effort */
  }
}

/**
 * v0.34.0 — convenience wrapper for emitting a `diagnostic` event.
 *
 * Diagnostics describe edge-case branches inside a normal handler
 * run (matcher returned no agents, WSL path rejected, MCP arg
 * coerced, etc.). They live in the project-local hook-events.jsonl
 * alongside the regular events so `stats --diagnostics` can count
 * them by code.
 *
 * If the projectRoot is not yet resolvable (the failure happened
 * before detection), prefer `appendError` from `core/error-log.ts`
 * — it falls back to a user-level path.
 *
 * Pure-ish: never throws. Same best-effort semantics as appendEvent.
 */
export async function appendDiagnostic(
  projectRoot: string,
  args: DiagnosticArgs,
): Promise<void> {
  await appendEvent(projectRoot, diagnosticEvent(args, Date.now()));
}

/**
 * Read all events from the current log file. Malformed JSONL lines are
 * skipped silently (a corrupted line should not poison the whole
 * dataset). Returns [] if the file is missing.
 */
export async function loadEvents(projectRoot: string): Promise<HookEvent[]> {
  let raw: string;
  try {
    raw = await fs.readFile(currentLogPath(projectRoot), "utf-8");
  } catch {
    return [];
  }
  const out: HookEvent[] = [];
  for (const line of raw.split("\n")) {
    if (!line.trim()) continue;
    try {
      out.push(JSON.parse(line) as HookEvent);
    } catch {
      // skip malformed
    }
  }
  return out;
}

/**
 * v0.33.0 (B5) — load events from EVERY `.token-pilot/hook-events.jsonl`
 * found at or below `repoRoot`. The hook writer resolves its own
 * project root from `process.cwd()` at the moment Claude Code spawns
 * us, which can land in a subdirectory of the actual repo (apps/admin,
 * apps/api, packages/prisma, …). Without this, `token-pilot stats`
 * sees only the top-level log and reports a fraction of the savings.
 *
 * Walks up to `maxDepth` levels and merges chronologically. Pure on
 * filesystem read errors — missing dirs are silently skipped.
 */
export async function loadEventsTree(
  repoRoot: string,
  maxDepth = 5,
): Promise<HookEvent[]> {
  const PRUNE = new Set([
    "node_modules",
    ".git",
    "dist",
    "build",
    ".next",
    ".turbo",
    ".cache",
    "coverage",
    ".vercel",
    ".vite",
  ]);
  const seen = new Set<string>();
  const all: HookEvent[] = [];

  async function visit(dir: string, depth: number): Promise<void> {
    if (depth > maxDepth) return;
    let entries: string[] = [];
    try {
      entries = await fs.readdir(dir);
    } catch {
      return;
    }
    if (entries.includes(".token-pilot")) {
      const logPath = join(dir, ".token-pilot", CURRENT_FILE);
      if (!seen.has(logPath)) {
        seen.add(logPath);
        try {
          const raw = await fs.readFile(logPath, "utf-8");
          for (const line of raw.split("\n")) {
            if (!line.trim()) continue;
            try {
              all.push(JSON.parse(line) as HookEvent);
            } catch {
              /* skip malformed */
            }
          }
        } catch {
          /* missing log */
        }
      }
    }
    for (const name of entries) {
      if (PRUNE.has(name)) continue;
      if (name.startsWith(".") && name !== ".claude") continue;
      const full = join(dir, name);
      try {
        const stat = await fs.stat(full);
        if (stat.isDirectory()) {
          await visit(full, depth + 1);
        }
      } catch {
        /* skip */
      }
    }
  }

  await visit(repoRoot, 0);
  // Sort chronologically so per-session aggregations stay correct.
  all.sort((a, b) => (a.ts || 0) - (b.ts || 0));
  return all;
}

/**
 * Enumerate all archive files (`hook-events.<ts>.jsonl`) with metadata
 * needed by `retentionDeletions`.
 */
async function listArchives(
  projectRoot: string,
): Promise<Array<{ path: string; mtime: Date; size: number }>> {
  const dir = eventLogDir(projectRoot);
  let entries: string[];
  try {
    entries = await fs.readdir(dir);
  } catch {
    return [];
  }
  const out: Array<{ path: string; mtime: Date; size: number }> = [];
  for (const name of entries) {
    if (!ARCHIVE_RE.test(name)) continue;
    const full = join(dir, name);
    try {
      const s = await fs.stat(full);
      out.push({ path: full, mtime: s.mtime, size: s.size });
    } catch {
      /* skip unreadable */
    }
  }
  return out;
}

/**
 * Apply age + size retention. Safe to call on startup; no-op when the
 * directory does not exist.
 */
export async function applyRetention(
  projectRoot: string,
  now: Date = new Date(),
): Promise<void> {
  const archives = await listArchives(projectRoot);
  const victims = retentionDeletions(archives, now);
  for (const p of victims) {
    try {
      await fs.unlink(p);
    } catch {
      /* ignore */
    }
  }
}

files.src/core/agent-matcher.ts:
/**
 * v0.31.0 — tp-* subagent heuristic matcher.
 *
 * Goal: given a Claude Code `Task` tool invocation (subagent_type +
 * description), decide which `tp-*` agent from `agents/` would be a
 * better fit. Used by:
 *
 *   1. PostToolUse:Task telemetry — enrich each event with
 *      `matched_tp_agent` so `stats --tasks` can show miss-rate.
 *   2. PreToolUse:Task enforcement (Pack 2, later) — advise/deny when
 *      the agent picked `general-purpose` but a tp-* clearly fits.
 *
 * Matcher philosophy — keep it BORING and EXPLAINABLE.
 *
 * Agent frontmatter description layout (empirically stable across all
 * 24 shipped agents):
 *
 *     description: PROACTIVELY use this when the user asks to review a
 *       diff, PR, commit range, or changeset ("review these changes",
 *       "look at my PR", "is this safe to merge"). Verdict-first output
 *       with Critical / Important findings. Do NOT use for writing code
 *       or planning.
 *
 * Two signal sources:
 *
 *   - Quoted triggers: every `"…"` substring inside the description.
 *     These are literally the phrases the agent author expected users
 *     to type. Highest signal. Substring match (case-insensitive) on
 *     the user's description → score += 2.
 *
 *   - Content keywords: stemmed word set from the 1st description
 *     sentence, minus stopwords and boilerplate ("PROACTIVELY",
 *     "use this", "when the user asks"). Each match on the user's
 *     description → score += 1.
 *
 * Negative filter: everything after `Do NOT use for` is excluded from
 * keyword extraction AND actively penalises a match (score -= 1 per
 * term present in user's description). Prevents `tp-test-writer` from
 * being suggested on "diagnose failing test" (which is tp-test-triage).
 *
 * Confidence tiers:
 *   - score ≥ 3 or a multi-word quoted trigger → "high"
 *   - score in [1, 2]                 → "low"
 *   - score < 1                       → no match
 *
 * The function is pure (deps → in-memory index + string) so it's fully
 * unit-testable. File I/O (reading the agents dir) lives in
 * `buildAgentIndex` which is a one-shot loader called at startup.
 */


/** One parsed `tp-*` agent. Only fields the matcher needs. */
export interface ParsedAgent {
  /** agent name without .md extension, e.g. "tp-pr-reviewer" */
  name: string;
  /** phrases found in `"…"` inside the description — highest signal */
  quotedTriggers: string[];
  /** stemmed content keywords from the positive side of the description */
  keywords: string[];
  /** negative-filter terms from `Do NOT use for …` */
  negative: string[];
}

export interface AgentIndex {
  agents: ParsedAgent[];
}

export interface MatchResult {
  agent: string;
  confidence: "high" | "low";
  score: number;
  /** A multi-word quoted trigger phrase matched — the only signal strong enough to block on. */
  phrase: boolean;
}

/**
 * Stopwords stripped from keyword extraction. Keep tiny — aggressive
 * stopword lists kill recall. Only boilerplate from agent frontmatter
 * templates goes here.
 */
const STOPWORDS = new Set([
  "a",
  "an",
  "the",
  "and",
  "or",
  "of",
  "to",
  "in",
  "for",
  "on",
  "at",
  "by",
  "is",
  "are",
  "was",
  "were",
  "be",
  "been",
  "being",
  "this",
  "that",
  "these",
  "those",
  "it",
  "its",
  "as",
  "with",
  "when",
  "where",
  "user",
  "users",
  "ask",
  "asks",
  "asked",
  "asking",
  "use",
  "uses",
  "used",
  "using",
  "proactively",
  "please",
  "any",
  "all",
  "some",
  "get",
  "gets",
  "got",
  "also",
  "like",
  "from",
  "into",
  "not",
  "no",
  "do",
  "does",
  "did",
  "have",
  "has",
  "had",
  "will",
  "can",
  "could",
  "should",
  "may",
  "might",
  "must",
  "you",
  "your",
  "their",
  "they",
  "them",
  "we",
  "our",
  "us",
]);

/** Extract the `description:` value from YAML frontmatter.
 *  Supports multi-line values (continuation lines indented).
 *  Returns null when the file has no frontmatter or no description. */
export function extractDescription(body: string): string | null {
  const fmEnd = body.indexOf("\n---", 3);
  if (!body.startsWith("---\n") || fmEnd === -1) return null;
  const fm = body.slice(4, fmEnd);
  const lines = fm.split("\n");

  let desc = "";
  let inDesc = false;

  for (const line of lines) {
    // Top-level key detection: `key: value` at column 0
    const topKey = /^([A-Za-z_][\w-]*)\s*:\s*(.*)$/.exec(line);
    if (topKey && !/^\s/.test(line)) {
      if (inDesc) break;
      if (topKey[1] === "description") {
        desc = topKey[2] ?? "";
        inDesc = true;
      }
    } else if (inDesc) {
      // Continuation line (indented or blank) — append with a space.
      desc += " " + line.trim();
    }
  }

  const trimmed = desc.trim();
  return trimmed.length > 0 ? trimmed : null;
}

/** Pull every `"…"` substring out of a string. Ignores empty pairs. */
export function extractQuotedTriggers(s: string): string[] {
  const out: string[] = [];
  const re = /"([^"]+)"/g;
  for (const m of s.matchAll(re)) {
    const inner = m[1].trim().toLowerCase();
    if (inner.length > 0) out.push(inner);
  }
  return out;
}

/**
 * Split `description` around `Do NOT use for …` — everything on the
 * positive side is keyword material; everything after contributes to
 * the negative filter.
 */
export function splitAroundNegative(desc: string): {
  positive: string;
  negative: string;
} {
  // Case-insensitive split on common "Do NOT use …" lead-ins. `to` catches
  // "Do NOT use to write" (tp-test-triage); `for` / `on` / `during` / `when`
  // cover every other shipped agent. Add terms here as new forms appear.
  const re = /\bdo\s+not\s+use\s+(?:for|on|during|when|to)\b/i;
  const idx = desc.search(re);
  if (idx === -1) return { positive: desc, negative: "" };
  return {
    positive: desc.slice(0, idx),
    negative: desc.slice(idx),
  };
}

/**
 * Tokenise → lowercase → drop stopwords + ≤2 chars + quoted-trigger
 * leftovers. Keywords stay in surface form; we do not stem. Stemming
 * helps recall on English verb/noun pairs ("refactor"/"refactoring"),
 * but libraries add cost for modest gain — use substring match on the
 * user's description instead (covers most morphology).
 */
export function extractKeywords(text: string): string[] {
  const out = new Set<string>();
  // Remove quoted phrases first (they're handled separately).
  const cleaned = text.replace(/"[^"]+"/g, " ");
  for (const raw of cleaned.toLowerCase().split(/[^a-z0-9_-]+/)) {
    const tok = raw.trim();
    // Keep short technical terms ("ci", "pr", "db", "io"). STOPWORDS already
    // filters most 1-2 char english junk ("is", "to", "on", "a"). Drop
    // single chars only — they carry ~no signal.
    if (tok.length < 2) continue;
    if (STOPWORDS.has(tok)) continue;
    out.add(tok);
  }
  return [...out];
}

/**
 * Parse one agent markdown body into its ParsedAgent representation.
 * Returns null if frontmatter is missing / description is empty.
 */
export function parseAgent(name: string, body: string): ParsedAgent | null {
  const desc = extractDescription(body);
  if (!desc) return null;
  const { positive, negative } = splitAroundNegative(desc);
  const quotedTriggers = extractQuotedTriggers(desc);
  const keywords = extractKeywords(positive);
  // Negative terms: only the core ones (tp-* names, salient nouns).
  const negKeywords = extractKeywords(negative);
  return {
    name,
    quotedTriggers,
    keywords,
    negative: negKeywords,
  };
}

/**
 * Index tp-*.md agent files the caller already read — from disk in the CLI
 * (core/agent-index-fs.ts), through `$.fs` in the Claude Code mod. Files that
 * are not tp-*.md, or do not parse, are skipped.
 */
export function buildAgentIndexFromFiles(
  files: ReadonlyArray<{ fileName: string; body: string }>,
): AgentIndex {
  const agents: ParsedAgent[] = [];
  for (const { fileName, body } of files) {
    if (!fileName.startsWith("tp-") || !fileName.endsWith(".md")) continue;
    const parsed = parseAgent(fileName.slice(0, -".md".length), body);
    if (parsed) agents.push(parsed);
  }

  return { agents };
}

/** Multi-word triggers may match in the prompt; one-word ones only in the description. */
function triggerHaystack(trigger: string, description: string, both: string): string {
  return trigger.includes(" ") ? both : description;
}

/**
 * A trigger phrase as whole words: "implement y" must not match
 * "implement your", nor "plan" match "planning".
 */
function hasPhrase(haystack: string, phrase: string): boolean {
  const escaped = phrase.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return new RegExp(`(?<![\\w])${escaped}(?![\\w])`).test(haystack);
}

/**
 * Score a single agent against the user description. Surface the score
 * so callers can inspect / threshold differently if needed.
 */
export function scoreAgent(
  agent: ParsedAgent,
  userDescriptionLower: string,
  extraLower = "",
): number {
  // Keywords and one-word triggers count on the short description only. A
  // long prompt is full of generic words ("how", "file", "only") and of
  // substrings like "plan" in "planning" that piled up to a confident, wrong
  // agent — and a hard deny. The prompt still counts through the author's
  // multi-word trigger phrases ("review these changes") and the negatives.
  const both = extraLower
    ? `${userDescriptionLower} ${extraLower}`
    : userDescriptionLower;
  let score = 0;

  for (const trigger of agent.quotedTriggers) {
    if (hasPhrase(triggerHaystack(trigger, userDescriptionLower, both), trigger)) {
      score += 2;
    }
  }

  for (const kw of agent.keywords) {
    if (userDescriptionLower.includes(kw)) score += 1;
  }

  for (const neg of agent.negative) {
    if (both.includes(neg)) score -= 1;
  }

  return score;
}

/**
 * Find the best `tp-*` match for a user description. Returns null when
 * no agent clears the low-confidence threshold.
 *
 * "Best" = highest score, tiebreak alphabetical (deterministic).
 */
export function matchTpAgent(
  description: string,
  index: AgentIndex,
  extra = "",
): MatchResult | null {
  if ((!description && !extra) || index.agents.length === 0) return null;
  const needle = description.toLowerCase();
  const extraLower = extra.toLowerCase();

  let best: { agent: ParsedAgent; score: number } | null = null;
  for (const agent of index.agents) {
    const score = scoreAgent(agent, needle, extraLower);
    if (!best) {
      best = { agent, score };
      continue;
    }
    if (score > best.score) {
      best = { agent, score };
      continue;
    }
    // Deterministic tiebreak: alphabetical by agent.name. Without this,
    // match depends on readdir order, which is filesystem-specific.
    if (score === best.score && agent.name < best.agent.name) {
      best = { agent, score };
    }
  }

  if (!best || best.score < 1) return null;

  // High confidence when score is strong OR a multi-word quoted trigger
  // matched (an explicit author-blessed phrase). A one-word trigger is just
  // a keyword: "plan" also fits "execute plan task 3".
  const both = extraLower ? `${needle} ${extraLower}` : needle;
  const phrase = best.agent.quotedTriggers.some(
    (t) => t.includes(" ") && hasPhrase(both, t),
  );
  const confidence: "high" | "low" =
    best.score >= 3 || phrase ? "high" : "low";

  return {
    agent: best.agent.name,
    confidence,
    score: best.score,
    phrase,
  };
}

/**
 * The tool Claude Code dispatches subagents with. It was renamed from
 * `Task` to `Agent`, and `Task` survives only as a legacy alias, so a hook
 * can be handed either name.
 */
export function isDispatchTool(toolName: unknown): boolean {
  return toolName === "Agent" || toolName === "Task";
}

/**
 * Drop a plugin namespace from an agent type. Claude Code reports plugin
 * agents as `token-pilot:tp-run`, while the catalog and the agent files
 * use the bare `tp-run`. Agent names cannot contain `:` themselves, so the
 * first colon is always the namespace separator.
 */
export function bareAgentName(agentType: string): string {
  return agentType.slice(agentType.indexOf(":") + 1);
}

